import "server-only";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { betterAuth } from "better-auth";
import { nextCookies } from "better-auth/next-js";

const databasePath = process.env.DATABASE_PATH ?? "data/notely.db";
mkdirSync(dirname(databasePath), { recursive: true });

export const googleEnabled = Boolean(
  process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET,
);

export const auth = betterAuth({
  database: new DatabaseSync(databasePath),
  emailAndPassword: {
    enabled: true,
    minPasswordLength: 8,
    // Sign the user straight in after sign-up; there is no email service to verify with yet.
    autoSignIn: true,
  },
  socialProviders: googleEnabled
    ? {
        google: {
          clientId: process.env.GOOGLE_CLIENT_ID!,
          clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
        },
      }
    : {},
  // Lets server actions set auth cookies through next/headers.
  plugins: [nextCookies()],
});
EOF

