cat > src/lib/users.ts <<'EOF'
import "server-only";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Users are stored in the Better Auth `user` table; this maps them to Notely's shape.
function toUser(u: { id: string; email: string; name: string; createdAt: Date }): User {
  return {
    id: u.id,
    email: u.email,
    name: u.name,
    createdAt: new Date(u.createdAt).toISOString().slice(0, 10),
  };
}

export async function listUsers(): Promise<User[]> {
  const ctx = await auth.$context;
  const users = await ctx.internalAdapter.listUsers(undefined, undefined, {
    field: "createdAt",
    direction: "asc",
  });
  return users.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const ctx = await auth.$context;
  const user = await ctx.internalAdapter.findUserById(id);
  return user ? toUser(user) : undefined;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? toUser(session.user) : undefined;
}

// Use in any page or action that must only run for signed-in users.
export async function requireUser(): Promise<User> {
  const user = await getCurrentUser();
  if (!user) redirect("/sign-in");
  return user;
}
EOF
